Iterator.ejemplo:
function* paginatedUsers(fetchPage: (cursor?: string) => Promise<Page>) {
  let cursor: string | undefined;
  do {
    const page = await fetchPage(cursor);
    for (const user of page.items) yield user;
    cursor = page.nextCursor;
  } while (cursor);
}

