Observer.ejemplo:
class EventEmitter<T> {
  private listeners = new Set<(payload: T) => void>();
  subscribe(fn: (payload: T) => void) {
    this.listeners.add(fn);
    return () => this.listeners.delete(fn);
  }
  emit(payload: T) { this.listeners.forEach((fn) => fn(payload)); }
}

