Proxy.ejemplo:
class CachedReportProxy implements ReportService {
  private cache = new Map<string, Report>();
  constructor(private readonly realService: ReportService) {}
  async getReport(id: string): Promise<Report> {
    if (!this.cache.has(id)) this.cache.set(id, await this.realService.getReport(id));
    return this.cache.get(id)!;
  }
}

