class TransferFundsService {
  constructor(private readonly accounts: AccountRepo, private readonly uow: UnitOfWork) {}
  async execute(fromId: string, toId: string, amount: Money) {
    return this.uow.run(async () => {
      const [from, to] = await Promise.all([this.accounts.get(fromId), this.accounts.get(toId)]);
      from.debit(amount); to.credit(amount);
      await this.accounts.saveAll([from, to]);
    });
  }
}

